int main(){
    mt19937_64 rng(999);
    double total=0;
    int T=300,n=300,Q=300;
    // pattern 0: random 60-bit
    for(int pattern=0; pattern<3; ++pattern){
        auto t0=chrono::high_resolution_clock::now();
        for(int tc=0; tc<T; ++tc){
            for(int i=1;i<=n;i++){
                if(pattern==0) a[i]=1+(rng()%( (ull)1<<60 ));
                else if(pattern==1) a[i]=1+(rng()%1000000);
                else a[i]=(1ULL<<60) - (i%7);
            }
            // process exactly like solution (no queries needed for timing)
            for(int r=1;r<=n;r++){
                ull ar=a[r]; ull cur=1;
                for(int l=r-1;l>=1;l--){
                    ull c=igcd(ar,a[l]);
                    if(cur%c!=0){ ull g=igcd(cur,c); cur=(cur/g)*c; }
                    G[l]=cur;
                }
                for(int l=1;l<=r-1;l++){
                    ull f=ar/G[l];
                    if(f!=1) dp[l]=dp[l]*(ll)(f%(ull)MOD)%MOD;
                }
                dp[r]=(ll)(ar%(ull)MOD);
            }
        }
        auto t1=chrono::high_resolution_clock::now();
        double ms=chrono::duration<double,milli>(t1-t0).count();
        total+=ms;
        printf("pattern %d: %.1f ms\n",pattern,ms);
    }
    printf("total %.1f ms\n",total);
