#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
typedef __uint128_t u128;
typedef long long ll;
static const ll MOD = 1000000007LL;

struct Big {
    vector<uint32_t> d;
    Big(ull x=0){ while(x){ d.push_back((uint32_t)(x&0xffffffffu)); x>>=32; } }
    ull mod64(ull m) const { u128 rem=0; for(int i=(int)d.size()-1;i>=0;--i){ rem=((rem<<32)|d[i])%m; } return (ull)rem; }
    void div64(ull g){ u128 rem=0; for(int i=(int)d.size()-1;i>=0;--i){ u128 cur=(rem<<32)|d[i]; d[i]=(uint32_t)(cur/g); rem=cur%g; } while(!d.empty()&&d.back()==0)d.pop_back(); }
    void mul64(ull m){ u128 carry=0; for(size_t i=0;i<d.size();++i){ u128 cur=(u128)d[i]*m+carry; d[i]=(uint32_t)(cur&0xffffffffu); carry=cur>>32; } while(carry){ d.push_back((uint32_t)(carry&0xffffffffu)); carry>>=32; } }
    ll modp(ll p) const { u128 rem=0; for(int i=(int)d.size()-1;i>=0;--i){ rem=((rem<<32)|d[i])%p; } return (ll)rem; }
};
static ull igcd(ull a, ull b){ while(b){ ull t=a%b; a=b; b=t;} return a; }

vector<ll> solve(const vector<ull>& a, int n, const vector<pair<int,int>>& qs){
    int Q=qs.size();
    vector<vector<pair<int,int>>> byr(n+1);
    for(int i=0;i<Q;i++) byr[qs[i].second].push_back({qs[i].first,i});
    vector<ll> ans(Q); vector<ll> dp(n+1,0); vector<ull> G(n+1,1);
    for(int r=1;r<=n;r++){
        ull ar=a[r]; ull cur=1;
        for(int l=r-1;l>=1;l--){ ull c=igcd(ar,a[l]); if(c!=1&&cur%c!=0){ ull g=igcd(cur,c); cur=(cur/g)*c; } G[l]=cur; }
        for(int l=1;l<=r-1;l++){ ull f=ar/G[l]; if(f!=1) dp[l]=dp[l]*(ll)(f%(ull)MOD)%MOD; }
        dp[r]=(ll)(ar%(ull)MOD);
        for(auto&pr:byr[r]) ans[pr.second]=dp[pr.first];
    }
    return ans;
}

