static void upd(int node,int l,int r,int ql,int qr,ll val){ if(ql>qr)return; if(ql<=l&&r<=qr){ lazy[node]=lazy[node]*val%MOD; return;} int mid=(l+r)>>1; if(ql<=mid)upd(node<<1,l,mid,ql,qr,val); if(qr>mid)upd(node<<1|1,mid+1,r,ql,qr,val); }
static ll qry(int node,int l,int r,int pos){ ll res=lazy[node]; if(l==r)return res; int mid=(l+r)>>1; if(pos<=mid)return res*qry(node<<1,l,mid,pos)%MOD; return res*qry(node<<1|1,mid+1,r,pos)%MOD; }
static double solve_time(const vector<vector<ull>>& tests){
    int T=tests.size(); int n=300; long long sink=0;
    auto t0=chrono::high_resolution_clock::now();
    for(int tc=0;tc<T;tc++){
        const auto& a=tests[tc];
        vector<vector<pair<ull,int>>> pf(n+1);
        for(int i=1;i<=n;i++){
            vector<ull> fs; ull x=a[i];
            for(ull p=2;p*p<=x && p<=1000;p+=(p==2?1:2)){ if(x%p==0){ int e=0; while(x%p==0){x/=p;e++;} for(int t=0;t<e;t++)fs.push_back(p);} }
            if(x>1) factor(x,fs);
            sort(fs.begin(),fs.end());
            for(size_t j=0;j<fs.size();){ size_t k=j; while(k<fs.size()&&fs[k]==fs[j])k++; pf[i].push_back({fs[j],(int)(k-j)}); j=k; }
        }
        fill(lazy,lazy+4*(n+1)+4,1LL);
        unordered_map<ull, vector<pair<int,int>>> st; st.reserve(2048);
        for(int r=1;r<=n;r++){
            for(auto& pe:pf[r]){
                ull p=pe.first; int e=pe.second; auto &S=st[p];
                bool popped=false; int pk=0;
                while(!S.empty()&&S.back().second<=e){ int s=S.back().first,v=S.back().second; S.pop_back(); int prev=S.empty()?0:S.back().first; ll fac=powmod(p%MOD,(ull)(e-v),MOD); upd(1,1,n,prev+1,s,fac); if(!popped){pk=s;popped=true;} }
                int sz; if(popped)sz=pk+1; else sz=S.empty()?1:S.back().first+1;
                ll fac=powmod(p%MOD,(ull)e,MOD); upd(1,1,n,sz,r,fac); S.push_back({r,e});
            }
            sink+=qry(1,1,n,r);
        }
    }
    auto t1=chrono::high_resolution_clock::now();
    if(sink==123456789) printf("");
    return chrono::duration<double,milli>(t1-t0).count();
}
int main(){
    mt19937_64 rng(123);
    ull MASK=((ull)1<<60)-1;
    int T=300,n=300;
    // random 60-bit
    vector<vector<ull>> A(T, vector<ull>(n+1));
    for(int t=0;t<T;t++)for(int i=1;i<=n;i++){ ull v=rng()&MASK; A[t][i]=v?v:1; }
    printf("random60 : %.1f ms\n", solve_time(A));
    // semiprimes p*q, p,q ~2^30
    vector<vector<ull>> B(T, vector<ull>(n+1));
    auto genPrime=[&](int bits)->ull{ for(;;){ ull p=(rng()&((1ULL<<bits)-1))|(1ULL<<(bits-1))|1; if(isPrime(p)) return p; } };
    for(int t=0;t<T;t++)for(int i=1;i<=n;i++){ ull p=genPrime(30),q=genPrime(30); ull v=p*q; if(v>(1ULL<<60)||v==0) i--; else B[t][i]=v; }
    printf("semiprime: %.1f ms\n", solve_time(B));
    // smooth numbers
    vector<vector<ull>> C(T, vector<ull>(n+1));
    vector<ull> smalls={2,3,5,7,11,13};
    for(int t=0;t<T;t++)for(int i=1;i<=n;i++){ ull v=1; for(int k=0;k<20;k++){ ull p=smalls[rng()%smalls.size()]; if(v>((~0ULL)/p))break; v*=p; } C[t][i]=v; }
    printf("smooth   : %.1f ms\n", solve_time(C));
    return 0;
}

